package com.company.platform.commerce.infrastructure.persistence;
import com.company.platform.commerce.domain.product.*;import java.sql.Timestamp;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Repository;
@Repository public class JdbcProductRepository implements ProductRepository { private final JdbcTemplate jdbc;public JdbcProductRepository(JdbcTemplate jdbc){this.jdbc=jdbc;} private Product map(java.sql.ResultSet r,int n)throws java.sql.SQLException{return Product.rehydrate(r.getObject("id",UUID.class),r.getObject("tenant_id",UUID.class),new SKU(r.getString("sku")),new ProductName(r.getString("name")),r.getString("description"),ProductStatus.valueOf(r.getString("status")),r.getTimestamp("created_at").toInstant(),r.getTimestamp("updated_at").toInstant());} public Product save(Product p){jdbc.update("INSERT INTO commerce_products(id,tenant_id,sku,name,description,status,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET name=EXCLUDED.name,description=EXCLUDED.description,status=EXCLUDED.status,updated_at=EXCLUDED.updated_at",p.id(),p.tenantId(),p.sku().value(),p.name().value(),p.description(),p.status().name(),Timestamp.from(p.createdAt()),Timestamp.from(p.updatedAt()));return p;} public Optional<Product> findByTenantIdAndId(UUID t,UUID id){return jdbc.query("SELECT * FROM commerce_products WHERE tenant_id=? AND id=?",this::map,t,id).stream().findFirst();} public Optional<Product> findByTenantIdAndSku(UUID t,String sku){return jdbc.query("SELECT * FROM commerce_products WHERE tenant_id=? AND sku=?",this::map,t,sku).stream().findFirst();} public List<Product> search(UUID t,String q,ProductStatus status){StringBuilder sql=new StringBuilder("SELECT * FROM commerce_products WHERE tenant_id=?");List<Object> a=new ArrayList<>();a.add(t);if(q!=null&&!q.isBlank()){sql.append(" AND (LOWER(name) LIKE LOWER(?) OR LOWER(sku) LIKE LOWER(?))");a.add("%"+q.trim()+"%");a.add("%"+q.trim()+"%");}if(status!=null){sql.append(" AND status=?");a.add(status.name());}sql.append(" ORDER BY name");return jdbc.query(sql.toString(),this::map,a.toArray());} }
